package dev.pocketengine.features.workspace;

import android.app.Application;
import dev.pocketengine.core.RunControl;
import dev.pocketengine.features.attachments.AttachmentRepository;
import dev.pocketengine.features.local.project.ProjectSources;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.*;
import static org.junit.Assert.*;

/** Five real module sections -> portable bytes -> fresh native host/SQL phases.
 * No account, real remote endpoint, SAF grant, process execution or model stub. */
@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,manifest=Config.NONE,application=Application.class)
@ConscryptMode(ConscryptMode.Mode.OFF)
public final class OwnerDataArchiveJourneyTest {
    @Before public void fixtureVault(){OwnerDataArchiveFixture.installFixtureVault();}
    @After public void releaseVault(){OwnerDataArchiveFixture.removeFixtureVault();}
    private static JSONObject json(String key,Object value)throws Exception{return new JSONObject().put(key,value);}
    private static String phase(OwnerDataArchiveFixture target,OwnerDataArchives archives,OwnerDataArchives.Selection selected,String name,String projects)throws Exception {
        var meta=selected.metadata();var map=target.host.ownerArchiveProjectMapForOwner(projects,meta.getString("archiveSha256"));var review=archives.review(selected,name,map,new RunControl());var confirmed=review.confirm();String action=confirmed.actionId();target.host.submitOwnerArchivePhaseForOwner(confirmed);long deadline=System.nanoTime()+10_000_000_000L;JSONObject row;
        do{row=target.tasks.ownerArchivePhaseForOwner(action);if(!row.getString("status").equals("running"))break;Thread.sleep(10);}while(System.nanoTime()<deadline);
        assertEquals("phase="+name+"; safe original state="+row,"completed",row.getString("status"));assertFalse(target.tasks.hasUnresolved(action));assertThrows(Exception.class,()->target.tasks.startAttempt(action,"capabilities",5));return action;
    }
    @Test public void fullPortableArchiveRestoresFiveExplicitSectionsToNewInstallAndColdQueriesNeverReplay()throws Exception {
        Path root=Files.createTempDirectory("owner-full-portable-");byte[] portable;String project,originalAttachment,firstSha;String originalProjectArtifact,retiredRevision;byte[] binary={0,9,(byte)255};String activeCheckout;
        try(var source=new OwnerDataArchiveFixture(RuntimeEnvironment.getApplication(),root.resolve("source-install"))){
            project=source.workspace.handle("create",json("name","原工程")).getString("id");var v1=source.workspace.writeBytesForHost(source.workspace.fileSnapshotForHost(project,"data.bin",0),binary);originalProjectArtifact=source.workspace.freezeFileForHost(v1,UUID.randomUUID().toString(),null,null).artifactId;var gone=source.workspace.deleteForHost(source.workspace.writeBytesForHost(source.workspace.fileSnapshotForHost(project,"deleted.bin",0),new byte[]{4}));retiredRevision=gone.revisionId;source.workspace.handle("write",json("projectId",project).put("path","main.py").put("expectedVersion",0).put("content","print('40.00')\n"));activeCheckout=source.local.handle("prepare",json("projectId",project)).getString("id");Path active=source.android.getFilesDir().toPath().resolve("local-development/checkouts/"+activeCheckout+"/files");Files.writeString(active.resolve("main.py"),"print('45.00 unsaved active tree')\n");
            var book=AttachmentRepository.get(source.android).book;JSONObject original=book.importBytes(new ByteArrayInputStream(binary),"native.bin","application/octet-stream",json("kind","owner_test_fixture"));originalAttachment=original.getString("id");firstSha=original.getString("sha256");book.importBytes(new ByteArrayInputStream("derived".getBytes(StandardCharsets.UTF_8)),"derived.txt","text/plain",json("kind","owner_test_fixture").put("parentArtifact",json("id",originalAttachment).put("sha256",firstSha)));
            source.memory.handle("save",json("record",json("layer","fact").put("text","这是主人明确保存的迁移内容").put("source","原生fixture")));source.remote.handle("saveProfile",json("id","original-computer").put("name","Own fixture computer").put("baseUrl","https://remote.example/companion").put("token","C2_FIXTURE_SECRET_NOT_IN_ARCHIVE"));source.ssh.handle("saveProfile",json("name","Own fixture SSH").put("host","ssh.example").put("port",2222).put("username","fixture").put("workspace","/work").put("authType","key"));
            var archives=source.host.ownerDataArchives(source.android);var selected=archives.create(OwnerDataArchives.SECTIONS,new RunControl());assertEquals(5,selected.metadata().getJSONObject("sections").length());ByteArrayOutputStream bytes=new ByteArrayOutputStream();archives.export(selected,bytes,new RunControl());portable=bytes.toByteArray();try(var zip=new java.util.zip.ZipInputStream(new ByteArrayInputStream(portable))){for(java.util.zip.ZipEntry entry;(entry=zip.getNextEntry())!=null;){assertFalse(new String(zip.readAllBytes(),StandardCharsets.UTF_8).contains("C2_FIXTURE_SECRET_NOT_IN_ARCHIVE"));zip.closeEntry();}}assertEquals(1,source.workspace.snapshot().getJSONArray("projects").length());
        }
        List<String> actions=new ArrayList<>();String archiveSha,newProject,newCheckout;int artifactCount,attachmentCount;Path destination=root.resolve("destination-install");
        try(var target=new OwnerDataArchiveFixture(RuntimeEnvironment.getApplication(),destination)){
            assertEquals(0,target.workspace.snapshot().getJSONArray("projects").length());var archives=target.host.ownerDataArchives(target.android);var selected=archives.read(new ByteArrayInputStream(portable),new RunControl());archiveSha=selected.metadata().getString("archiveSha256");assertEquals(0,target.workspace.snapshot().getJSONArray("projects").length());assertEquals(0,target.remote.snapshot().getJSONArray("profiles").length());String projectAction=phase(target,archives,selected,"projects","");actions.add(projectAction);JSONObject restored=target.host.queryOwnerArchivePhaseForOwner(projectAction,new RunControl());newProject=restored.getJSONObject("projectMap").getString(project);assertNotEquals(project,newProject);JSONArray copies=restored.getJSONArray("checkouts");newCheckout=copies.getJSONObject(0).getString("id");assertNotEquals(activeCheckout,newCheckout);Path active=target.android.getFilesDir().toPath().resolve("local-development/checkouts/"+newCheckout+"/files");assertEquals("print('45.00 unsaved active tree')\n",Files.readString(active.resolve("main.py")));assertTrue(target.workspace.fileSnapshotForHost(newProject,"deleted.bin",0).tombstone);assertNotEquals(retiredRevision,target.workspace.fileSnapshotForHost(newProject,"deleted.bin",0).revisionId);assertArrayEquals(binary,target.workspace.fileSnapshotForHost(newProject,"data.bin",0).bytes());
            for(String name:List.of("artifacts","memory","remoteConnections","sshConnections"))actions.add(phase(target,archives,selected,name,projectAction));artifactCount=target.workspace.snapshot().getJSONArray("artifacts").length();assertEquals(1,artifactCount);JSONObject fixed=target.workspace.snapshot().getJSONArray("artifacts").getJSONObject(0);assertNotEquals(originalProjectArtifact,fixed.getString("id"));assertArrayEquals(binary,target.workspace.fileArtifactBytesForHost(target.workspace.fileArtifactForHost(fixed.getString("id"),firstSha)));assertFalse(fixed.has("taskId"));var book=AttachmentRepository.get(target.android).book;attachmentCount=book.list().length();assertEquals(2,attachmentCount);boolean sawParent=false;for(int i=0;i<attachmentCount;i++){JSONObject record=book.list().getJSONObject(i);assertNotEquals(originalAttachment,record.getString("id"));assertFalse(record.has("uri"));JSONObject source=record.optJSONObject("source");if(source!=null&&source.optJSONObject("parentArtifact")!=null){assertNotEquals(originalAttachment,source.getJSONObject("parentArtifact").getString("id"));sawParent=true;}}assertTrue(sawParent);JSONObject memories=target.memory.handle("list",new JSONObject());assertEquals(1,memories.getJSONArray("records").length());JSONObject memory=memories.getJSONArray("records").getJSONObject(0);assertTrue(memory.getBoolean("archiveOnly"));assertFalse(memory.getBoolean("active"));assertEquals(0,memory.getJSONArray("sourceRefs").length());JSONObject remote=target.remote.snapshot().getJSONArray("profiles").getJSONObject(0),ssh=target.ssh.snapshot().getJSONArray("profiles").getJSONObject(0);assertNotEquals("original-computer",remote.getString("id"));assertFalse(remote.getBoolean("hasToken"));assertFalse(ssh.getBoolean("credentialsConfigured"));assertFalse(ssh.getBoolean("hostKeyTrusted"));assertEquals(0,target.remote.snapshot().getJSONArray("operations").length());assertEquals(0,target.ssh.snapshot().getJSONArray("operations").length());
        }
        try(var cold=new OwnerDataArchiveFixture(RuntimeEnvironment.getApplication(),destination)){
            cold.host.ownerDataArchives(cold.android);for(String action:actions){JSONObject result=cold.host.queryOwnerArchivePhaseForOwner(action,new RunControl());assertTrue(result.toString(),result.getBoolean("found"));assertEquals("completed",cold.tasks.ownerArchivePhaseForOwner(action).getString("status"));assertFalse(cold.tasks.hasUnresolved(action));}assertEquals(1,cold.workspace.snapshot().getJSONArray("projects").length());assertEquals(1,cold.local.snapshot().getJSONArray("checkouts").length());assertEquals(artifactCount,cold.workspace.snapshot().getJSONArray("artifacts").length());assertEquals(attachmentCount,AttachmentRepository.get(cold.android).book.list().length());assertEquals(1,cold.remote.snapshot().getJSONArray("profiles").length());assertEquals(1,cold.ssh.snapshot().getJSONArray("profiles").length());
        }
    }
    @Test public void persistedPreDispatchIntentIsUnknownAndBlocksCacheRemovalOrNewRestoreWithoutReplay()throws Exception {
        Path root=Files.createTempDirectory("owner-archive-intent-");try(var target=new OwnerDataArchiveFixture(RuntimeEnvironment.getApplication(),root)){
            target.workspace.handle("create",json("name","不能重复恢复"));var archives=target.host.ownerDataArchives(target.android);var selected=archives.create(Set.of("projects"),new RunControl());String sha=selected.metadata().getString("archiveSha256");var review=archives.review(selected,"projects",target.host.ownerArchiveProjectMapForOwner("",sha),new RunControl());var confirmed=review.confirm();String original=confirmed.actionId();target.tasks.beginOwnerArchivePhaseForOwner(confirmed);JSONObject observed=target.host.queryOwnerArchivePhaseForOwner(original,new RunControl());assertFalse(observed.getBoolean("found"));assertEquals("reconciling",target.tasks.ownerArchivePhaseForOwner(original).getString("status"));assertTrue(target.tasks.hasUnresolved(original));assertThrows(Exception.class,()->target.host.discardOwnerArchiveCacheForOwner(selected,new RunControl()));var another=archives.review(selected,"projects",target.host.ownerArchiveProjectMapForOwner("",sha),new RunControl()).confirm();assertThrows(Exception.class,()->target.tasks.beginOwnerArchivePhaseForOwner(another));assertEquals(1,target.workspace.snapshot().getJSONArray("projects").length());assertEquals(0,target.local.snapshot().getJSONArray("checkouts").length());assertThrows(Exception.class,()->target.tasks.startAttempt(original,"capabilities",5));var cancel=new RunControl();cancel.cancel();assertThrows(InterruptedException.class,()->archives.review(selected,"projects",target.host.ownerArchiveProjectMapForOwner("",sha),cancel));assertEquals(1,target.workspace.snapshot().getJSONArray("projects").length());
        }
    }
}
